const string randomSource="using TKR.WorldServer.logic.transitions;namespace TKR.WorldServer.logic{public partial class BehaviorDb{private _ StudioRandomObservation=()=>Behav().Init(\"Cave Pirate Brawler\",new State(new State(\"choose\",new TimedRandomTransition(0,false,\"a\",\"a\",\"b\")),new State(\"a\",new TimedTransition(0,\"choose\")),new State(\"b\",new TimedTransition(0,\"choose\"))));}}";var randomDoc=new BehaviorDocument(randomSource,adapter,sourceFile:file);string[] phases=[];await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project with{Source=randomSource,Identities=randomDoc.Identities})){await native.AdvanceAsync(new(),1000);var choices=native.Callbacks.Where(c=>c.Behavior.EndsWith("TimedRandomTransition")).ToArray();Check(choices.Length>0&&choices.All(c=>c.Transition is{Matched:true,SelectedIndex:>=0 and <3}&&c.Transition.Target==(c.Transition.SelectedIndex<2?"a":"b")),"Observed random choices retain the game's actual repeated-slot weighting and selected indices");phases=native.Events.Where(e=>e.Kind=="transition").Select(e=>e.Message).ToArray();}await using(var plain=await CompiledRuntime.StartAsync(adapter.ServerRoot,project with{Source=randomSource,Identities=randomDoc.Identities},captureStateOrigins:false)){await plain.AdvanceAsync(new(),1000);Check(plain.Events.Where(e=>e.Kind=="transition").Select(e=>e.Message).SequenceEqual(phases),"Transition result observation does not add RNG draws or alter native weighted choices");}
const string customSource="""
using TKR.WorldServer.logic.behaviors;
using TKR.WorldServer.core.objects;
using TKR.WorldServer.core.worlds;
using TKR.WorldServer.networking.packets.outgoing;
namespace TKR.WorldServer.logic {public partial class BehaviorDb {
    private _ StudioCustomTransition=()=>Behav().Init("Cave Pirate Brawler",new State(new State("go",new ObservedTransition(new Shoot(20,count:4,fixedAngle:0,coolDown:100),"done")),new State("done")));
    sealed class ObservedTransition:Transition {
        readonly Behavior child;public ObservedTransition(Behavior child,string target):base(target)=>this.child=child;
        protected override bool TickCore(Entity host,TickTime time,ref object state){child.Tick(host,time);host.World.BroadcastIfVisible(new ShowEffect{EffectType=EffectType.LedgerMark,TargetObjectId=host.Id,Duration=100},host);return false;}
        public override void OnDeath(Entity host,ref TickTime time)=>host.World.BroadcastIfVisible(new ShowEffect{EffectType=EffectType.LedgerMark,TargetObjectId=host.Id,Duration=800},host);
    }
} }
